def mod1(x, N, y=None):
    a = numpyro.sample("a", dist.Normal(0, 5))
    b = numpyro.sample("b", dist.Normal(0, 5))
    with numpyro.plate("J", len(N)):
        return numpyro.sample("y", dist.BinomialLogits(total_count=N, logits=a + b*x), obs=y)



